from itertools import permutations

people = ["Casey", "Jordan", "Parker", "Sawyer"]
colors = ["blue", "green", "orange", "white"]
pets = ["cat", "fish", "horse", "rabbit"]
drinks = ["cocoa", "milk", "tea", "water"]

def is_valid(house):
    # Extract positions for quick lookup
    pos = {}
    for i in range(4):
        pos[('person', house[i]['person'])] = i
        pos[('color', house[i]['color'])] = i
        pos[('pet', house[i]['pet'])] = i
        pos[('drink', house[i]['drink'])] = i

    # Clue 1: Blue house lives next to horse owner
    if abs(pos[('color', 'blue')] - pos[('pet', 'horse')]) != 1:
        return False

    # Clue 2: Tea drinker immediately left of orange house
    if pos[('color', 'orange')] != pos[('drink', 'tea')] + 1:
        return False

    # Clue 3: Casey immediately left of rabbit owner
    if pos[('pet', 'rabbit')] != pos[('person', 'Casey')] + 1:
        return False

    # Clue 4: Cat owner lives next to orange house
    if abs(pos[('pet', 'cat')] - pos[('color', 'orange')]) != 1:
        return False

    # Clue 5: Parker lives next to rabbit owner
    if abs(pos[('person', 'Parker')] - pos[('pet', 'rabbit')]) != 1:
        return False

    # Clue 6: Rabbit owner in white house
    rabbit_pos = pos[('pet', 'rabbit')]
    if house[rabbit_pos]['color'] != 'white':
        return False

    # Clue 7: Green house immediately left of rabbit owner
    if pos[('pet', 'rabbit')] != pos[('color', 'green')] + 1:
        return False

    # Clue 8: Parker doesn't drink cocoa
    parker_pos = pos[('person', 'Parker')]
    if house[parker_pos]['drink'] == 'cocoa':
        return False

    # Clue 9: Horse owner immediately left of Sawyer
    if pos[('person', 'Sawyer')] != pos[('pet', 'horse')] + 1:
        return False

    # Clue 10: Water drinker is Casey
    casey_pos = pos[('person', 'Casey')]
    if house[casey_pos]['drink'] != 'water':
        return False

    return True

def solve():
    for people_perm in permutations(people):
        for colors_perm in permutations(colors):
            for pets_perm in permutations(pets):
                for drinks_perm in permutations(drinks):
                    house = [
                        {'person': people_perm[i], 'color': colors_perm[i], 'pet': pets_perm[i], 'drink': drinks_perm[i]}
                        for i in range(4)
                    ]

                    if is_valid(house):
                        # Find who drinks water
                        for i in range(4):
                            if house[i]['drink'] == 'water':
                                return house[i]['person']
    return None

answer = solve()
print(f"ANSWER: {answer}")
